mapper.update:
UPDATE chat_group_member
SET last_read_msg_id = # {msgId}
WHERE group_id = #{groupId} AND user_id = #{userId}

mapper.select:
SELECT last_read_msg_id
FROM chat_group_member
WHERE group_id = #{groupId} AND user_id = #{userId}

SELECT id, msg_id as msgId, from_user as fromUser, to_user as toUser, group_id as groupId,
       content, cmd, is_read as isRead, is_offline as isOffline, create_time as createTime
FROM chat_message
WHERE group_id = #{groupId}
  AND cmd = 3
  AND create_time >
      COALESCE((
                   SELECT cm2.create_time
                   FROM chat_message cm2
                   WHERE cm2.group_id = #{groupId}
                     AND cm2.msg_id = #{cursorMsgId}
                   LIMIT 1
                   ), '1970-01-01')
ORDER BY create_time ASC
LIMIT #{limit}
